insert into public.exercises(title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url) select title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url from jsonb_populate_record(null::public.exercises,'{"title": "Спокойно повернуть голову", "body_zone": "neck", "target_zones": ["neck"], "duration_seconds": 60, "repetitions": "По 3 раза в каждую сторону", "instructions": "Сядьте устойчиво, смотрите перед собой.\nМедленно поверните голову в комфортном диапазоне, без усилия.\nВернитесь в исходное положение и повторите в другую сторону.", "description": "Небольшое движение во время перерыва.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.nhs.uk/live-well/exercise/sitting-exercises/", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb) where not exists(select 1 from public.exercises where title='{"title": "Спокойно повернуть голову", "body_zone": "neck", "target_zones": ["neck"], "duration_seconds": 60, "repetitions": "По 3 раза в каждую сторону", "instructions": "Сядьте устойчиво, смотрите перед собой.\nМедленно поверните голову в комфортном диапазоне, без усилия.\nВернитесь в исходное положение и повторите в другую сторону.", "description": "Небольшое движение во время перерыва.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.nhs.uk/live-well/exercise/sitting-exercises/", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb->>'title');
insert into public.exercises(title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url) select title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url from jsonb_populate_record(null::public.exercises,'{"title": "Мягко раскрыть плечи", "body_zone": "shoulders", "target_zones": ["shoulders", "upper_back"], "duration_seconds": 60, "repetitions": "5 спокойных повторений", "instructions": "Сядьте устойчиво и опустите плечи.\nМягко сведите лопатки без сильного прогиба.\nРасслабьте плечи и вернитесь в удобное положение.", "description": "Короткая смена положения плеч.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.nhs.uk/live-well/exercise/sitting-exercises/", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb) where not exists(select 1 from public.exercises where title='{"title": "Мягко раскрыть плечи", "body_zone": "shoulders", "target_zones": ["shoulders", "upper_back"], "duration_seconds": 60, "repetitions": "5 спокойных повторений", "instructions": "Сядьте устойчиво и опустите плечи.\nМягко сведите лопатки без сильного прогиба.\nРасслабьте плечи и вернитесь в удобное положение.", "description": "Короткая смена положения плеч.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.nhs.uk/live-well/exercise/sitting-exercises/", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb->>'title');
insert into public.exercises(title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url) select title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url from jsonb_populate_record(null::public.exercises,'{"title": "Поднять колени сидя", "body_zone": "hips", "target_zones": ["hips", "knees"], "duration_seconds": 60, "repetitions": "По 5 раз каждой ногой", "instructions": "Сядьте на устойчивый стул, стопы поставьте на пол.\nПоднимите одну стопу, слегка согнув бедро.\nПлавно опустите и повторите другой ногой.", "description": "Лёгкое движение ног сидя.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.nhs.uk/live-well/exercise/sitting-exercises/", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb) where not exists(select 1 from public.exercises where title='{"title": "Поднять колени сидя", "body_zone": "hips", "target_zones": ["hips", "knees"], "duration_seconds": 60, "repetitions": "По 5 раз каждой ногой", "instructions": "Сядьте на устойчивый стул, стопы поставьте на пол.\nПоднимите одну стопу, слегка согнув бедро.\nПлавно опустите и повторите другой ногой.", "description": "Лёгкое движение ног сидя.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.nhs.uk/live-well/exercise/sitting-exercises/", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb->>'title');
insert into public.exercises(title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url) select title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url from jsonb_populate_record(null::public.exercises,'{"title": "Движения стопами сидя", "body_zone": "feet", "target_zones": ["feet"], "duration_seconds": 60, "repetitions": "По 5 раз каждой стопой", "instructions": "Сядьте устойчиво.\nВытяните одну ногу в удобное положение.\nПлавно направьте носок от себя и к себе, без напряжения.\nПоставьте стопу на пол, повторите другой ногой.", "description": "Мягкая разминка стоп.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.nhs.uk/live-well/exercise/sitting-exercises/", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb) where not exists(select 1 from public.exercises where title='{"title": "Движения стопами сидя", "body_zone": "feet", "target_zones": ["feet"], "duration_seconds": 60, "repetitions": "По 5 раз каждой стопой", "instructions": "Сядьте устойчиво.\nВытяните одну ногу в удобное положение.\nПлавно направьте носок от себя и к себе, без напряжения.\nПоставьте стопу на пол, повторите другой ногой.", "description": "Мягкая разминка стоп.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.nhs.uk/live-well/exercise/sitting-exercises/", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb->>'title');
insert into public.exercises(title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url) select title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url from jsonb_populate_record(null::public.exercises,'{"title": "Короткая прогулка", "body_zone": "posture", "target_zones": ["hips", "knees", "feet", "lower_back"], "duration_seconds": 120, "repetitions": "В комфортном темпе", "instructions": "Отойдите от экрана.\nПройдитесь по свободному безопасному пространству в удобном темпе.\nВернитесь, когда будете готовы.", "description": "Смена деятельности во время перерыва.", "applicability": {"space": ["walking"]}, "source_url": "https://www.osha.gov/etools/computer-workstations/work-process", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb) where not exists(select 1 from public.exercises where title='{"title": "Короткая прогулка", "body_zone": "posture", "target_zones": ["hips", "knees", "feet", "lower_back"], "duration_seconds": 120, "repetitions": "В комфортном темпе", "instructions": "Отойдите от экрана.\nПройдитесь по свободному безопасному пространству в удобном темпе.\nВернитесь, когда будете готовы.", "description": "Смена деятельности во время перерыва.", "applicability": {"space": ["walking"]}, "source_url": "https://www.osha.gov/etools/computer-workstations/work-process", "difficulty": "easy", "limitations": ["Не выполнять при боли, усилении ощущений или индивидуальном запрете специалиста."], "is_active": true}'::jsonb->>'title');
insert into public.exercises(title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url) select title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url from jsonb_populate_record(null::public.exercises,'{"title": "Сменить положение сидя", "body_zone": "back", "target_zones": ["upper_back", "lower_back", "hips"], "duration_seconds": 60, "repetitions": "Одна спокойная смена положения", "description": "Небольшая пауза без специальных растягивающих движений.", "instructions": "Остановите работу за экраном.\nНайдите другую удобную опору для спины и ног.\nСмените положение без усилия, сохраняя устойчивость.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.osha.gov/etools/computer-workstations/work-process", "difficulty": "easy", "limitations": ["Не выполнять через боль или вопреки индивидуальным ограничениям."], "is_active": true}'::jsonb) where not exists(select 1 from public.exercises where title='{"title": "Сменить положение сидя", "body_zone": "back", "target_zones": ["upper_back", "lower_back", "hips"], "duration_seconds": 60, "repetitions": "Одна спокойная смена положения", "description": "Небольшая пауза без специальных растягивающих движений.", "instructions": "Остановите работу за экраном.\nНайдите другую удобную опору для спины и ног.\nСмените положение без усилия, сохраняя устойчивость.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.osha.gov/etools/computer-workstations/work-process", "difficulty": "easy", "limitations": ["Не выполнять через боль или вопреки индивидуальным ограничениям."], "is_active": true}'::jsonb->>'title');
insert into public.exercises(title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url) select title,body_zone,difficulty,duration_seconds,description,instructions,target_zones,repetitions,limitations,applicability,source_url from jsonb_populate_record(null::public.exercises,'{"title": "Пауза для кистей и предплечий", "body_zone": "wrists", "target_zones": ["wrists", "elbows"], "duration_seconds": 60, "repetitions": "Одна короткая пауза", "description": "Перерыв от клавиатуры, мыши или удержания устройства.", "instructions": "Прекратите набор текста или работу указателем.\nПоложите устройство и удобно расположите руки на мягкой опоре.\nРасслабьте кисти без сильного растягивания и сжатия.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.osha.gov/etools/computer-workstations/work-process", "difficulty": "easy", "limitations": ["Не выполнять через боль или вопреки индивидуальным ограничениям."], "is_active": true}'::jsonb) where not exists(select 1 from public.exercises where title='{"title": "Пауза для кистей и предплечий", "body_zone": "wrists", "target_zones": ["wrists", "elbows"], "duration_seconds": 60, "repetitions": "Одна короткая пауза", "description": "Перерыв от клавиатуры, мыши или удержания устройства.", "instructions": "Прекратите набор текста или работу указателем.\nПоложите устройство и удобно расположите руки на мягкой опоре.\nРасслабьте кисти без сильного растягивания и сжатия.", "applicability": {"space": ["seated", "standing", "walking"]}, "source_url": "https://www.osha.gov/etools/computer-workstations/work-process", "difficulty": "easy", "limitations": ["Не выполнять через боль или вопреки индивидуальным ограничениям."], "is_active": true}'::jsonb->>'title');
insert into public.articles(title,category,content,target_zones,source_url) select title,category,content,target_zones,source_url from jsonb_populate_record(null::public.articles,'{"title": "Экран и рабочее место", "category": "workplace", "target_zones": ["neck", "shoulders", "upper_back"], "content": "Начните с основного экрана: расположите его перед собой, подберите высоту, при которой не приходится сильно наклонять или запрокидывать голову. Увеличьте текст, если приходится приближаться. Если поднимаете ноутбук, отдельная клавиатура помогает независимо настроить положение рук. Меняйте настройки постепенно и отмечайте, стало ли удобнее.", "source_url": "https://www.osha.gov/etools/computer-workstations/components/monitors"}'::jsonb) where not exists(select 1 from public.articles where title='{"title": "Экран и рабочее место", "category": "workplace", "target_zones": ["neck", "shoulders", "upper_back"], "content": "Начните с основного экрана: расположите его перед собой, подберите высоту, при которой не приходится сильно наклонять или запрокидывать голову. Увеличьте текст, если приходится приближаться. Если поднимаете ноутбук, отдельная клавиатура помогает независимо настроить положение рук. Меняйте настройки постепенно и отмечайте, стало ли удобнее.", "source_url": "https://www.osha.gov/etools/computer-workstations/components/monitors"}'::jsonb->>'title');
insert into public.articles(title,category,content,target_zones,source_url) select title,category,content,target_zones,source_url from jsonb_populate_record(null::public.articles,'{"title": "Руки и устройства ввода", "category": "workplace", "target_zones": ["wrists", "elbows", "shoulders"], "content": "Расположите мышь рядом с клавиатурой. Найдите положение, в котором предплечья имеют удобную опору, а кисти не приходится заметно сгибать. Избегайте давления о жёсткий край стола. Настройка должна быть удобной именно вам; попробуйте несколько вариантов.", "source_url": "https://www.osha.gov/etools/computer-workstations/components/keyboards"}'::jsonb) where not exists(select 1 from public.articles where title='{"title": "Руки и устройства ввода", "category": "workplace", "target_zones": ["wrists", "elbows", "shoulders"], "content": "Расположите мышь рядом с клавиатурой. Найдите положение, в котором предплечья имеют удобную опору, а кисти не приходится заметно сгибать. Избегайте давления о жёсткий край стола. Настройка должна быть удобной именно вам; попробуйте несколько вариантов.", "source_url": "https://www.osha.gov/etools/computer-workstations/components/keyboards"}'::jsonb->>'title');
insert into public.articles(title,category,content,target_zones,source_url) select title,category,content,target_zones,source_url from jsonb_populate_record(null::public.articles,'{"title": "Перерывы, которые вписываются в день", "category": "breaks", "target_zones": [], "content": "Чередуйте работу за экраном с другой деятельностью. Короткие регулярные паузы легче встроить в день, чем редкий длинный перерыв. Отведите взгляд от экрана, смените положение или немного пройдитесь, если это доступно. Выберите интервал, который подходит занятиям и встречам.", "source_url": "https://www.osha.gov/etools/computer-workstations/work-process"}'::jsonb) where not exists(select 1 from public.articles where title='{"title": "Перерывы, которые вписываются в день", "category": "breaks", "target_zones": [], "content": "Чередуйте работу за экраном с другой деятельностью. Короткие регулярные паузы легче встроить в день, чем редкий длинный перерыв. Отведите взгляд от экрана, смените положение или немного пройдитесь, если это доступно. Выберите интервал, который подходит занятиям и встречам.", "source_url": "https://www.osha.gov/etools/computer-workstations/work-process"}'::jsonb->>'title');
insert into public.articles(title,category,content,target_zones,source_url) select title,category,content,target_zones,source_url from jsonb_populate_record(null::public.articles,'{"title": "Когда стоит обсудить ощущения со специалистом", "category": "safety", "target_zones": [], "content": "Новые, сильные или нарастающие ощущения, онемение, слабость, последствия травмы и внезапные изменения зрения требуют индивидуальной оценки. Автоматический план не определяет причину симптомов. Не продолжайте движение, если оно вызывает боль или ухудшает состояние.", "source_url": "https://www.osha.gov/etools/computer-workstations/work-process"}'::jsonb) where not exists(select 1 from public.articles where title='{"title": "Когда стоит обсудить ощущения со специалистом", "category": "safety", "target_zones": [], "content": "Новые, сильные или нарастающие ощущения, онемение, слабость, последствия травмы и внезапные изменения зрения требуют индивидуальной оценки. Автоматический план не определяет причину симптомов. Не продолжайте движение, если оно вызывает боль или ухудшает состояние.", "source_url": "https://www.osha.gov/etools/computer-workstations/work-process"}'::jsonb->>'title');
